content.text:
[
  {
    "service": "TimesheetService",
    "method": "getTimesheets",
    "description": "List timesheets.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "query",
        "type": "Object",
        "description": "Filter: { page?, pageSize?, employeeId?, status? }",
        "required": false
      }
    ],
    "returns": "Paginated DTO of bm_timesheet BaseModels.",
    "group": "business-made"
  },
  {
    "service": "TimesheetService",
    "method": "getTimesheet",
    "description": "Fetch a single timesheet by sk.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "id",
        "type": "String",
        "description": "sk of the bm_timesheet.",
        "required": true
      }
    ],
    "returns": "BaseModel<bm_timesheet> or null.",
    "group": "business-made"
  },
  {
    "service": "TimesheetService",
    "method": "createTimesheet",
    "description": "Create a timesheet for an employee/pay period. Throws CONFLICT if one already exists for the same period.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "data",
        "type": "Object",
        "description": "Timesheet payload (e.g., { employeeId, payPeriodStart, payPeriodEnd }).",
        "required": true
      },
      {
        "name": "author",
        "type": "String",
        "description": "Audit-trail label; defaults to \"system\".",
        "required": false
      }
    ],
    "returns": "The persisted bm_timesheet BaseModel.",
    "group": "business-made"
  },
  {
    "service": "TimesheetService",
    "method": "updateTimesheet",
    "description": "Update a timesheet in full.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "data",
        "type": "Object",
        "description": "Full bm_timesheet BaseModel including sk and updated data.",
        "required": true
      }
    ],
    "returns": "The updated bm_timesheet BaseModel.",
    "group": "business-made"
  },
  {
    "service": "TimesheetService",
    "method": "deleteTimesheet",
    "description": "Delete a timesheet — allowed for a draft or rejected sheet, or one with no entries. Never a paid sheet, one with an open clock-in, or hours in a pay period locked for payroll.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "id",
        "type": "String",
        "description": "sk of the bm_timesheet.",
        "required": true
      },
      {
        "name": "deletedBy",
        "type": "String",
        "description": "Audit-trail label; defaults to \"system\".",
        "required": false
      }
    ],
    "returns": "Delete result from the repository.",
    "group": "business-made"
  },
  {
    "service": "TimesheetService",
    "method": "getTimesheetsByEmployee",
    "description": "List timesheets for one employee.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "employeeId",
        "type": "String",
        "description": "Employee ID — the badge number, e.g. EMP-1043.",
        "required": true
      },
      {
        "name": "query",
        "type": "Object",
        "description": "Filter: { page?, pageSize? }",
        "required": false
      }
    ],
    "returns": "Paginated DTO of bm_timesheet BaseModels.",
    "group": "business-made"
  },
  {
    "service": "TimesheetService",
    "method": "getTimesheetByEmployeeAndPeriod",
    "description": "Look up a timesheet for a specific employee and pay period.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "employeeId",
        "type": "String",
        "description": "Employee ID — the badge number, e.g. EMP-1043.",
        "required": true
      },
      {
        "name": "periodStart",
        "type": "String",
        "description": "ISO date YYYY-MM-DD.",
        "required": true
      },
      {
        "name": "periodEnd",
        "type": "String",
        "description": "ISO date YYYY-MM-DD.",
        "required": true
      }
    ],
    "returns": "The matching bm_timesheet BaseModel or null.",
    "group": "business-made"
  },
  {
    "service": "TimesheetService",
    "method": "getPendingTimesheets",
    "description": "List timesheets pending approval (status = submitted).",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "query",
        "type": "Object",
        "required": false
      }
    ],
    "returns": "Paginated DTO of submitted bm_timesheet BaseModels.",
    "group": "business-made"
  },
  {
    "service": "TimesheetService",
    "method": "getTimesheetsByStatus",
    "description": "List timesheets filtered by status.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "status",
        "type": "String",
        "description": "Status filter (draft|submitted|approved|rejected).",
        "required": true
      },
      {
        "name": "query",
        "type": "Object",
        "description": "Filter: { page?, pageSize? }",
        "required": false
      }
    ],
    "returns": "Paginated DTO of bm_timesheet BaseModels.",
    "group": "business-made"
  },
  {
    "service": "TimesheetService",
    "method": "submitTimesheet",
    "description": "Submit a draft timesheet for approval. Refuses if not draft or has zero entries.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "id",
        "type": "String",
        "description": "sk of the bm_timesheet.",
        "required": true
      },
      {
        "name": "submittedById",
        "type": "String",
        "description": "Identifier of submitter.",
        "required": true
      }
    ],
    "returns": "The updated bm_timesheet BaseModel.",
    "group": "business-made"
  },
  {
    "service": "TimesheetService",
    "method": "approveTimesheet",
    "description": "Approve a submitted timesheet — sets status approved, marks all entries approved. Refuses unless status is \"submitted\".",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "id",
        "type": "String",
        "description": "sk of the bm_timesheet.",
        "required": true
      },
      {
        "name": "approvedById",
        "type": "String",
        "description": "Identifier of approver.",
        "required": true
      }
    ],
    "returns": "The updated bm_timesheet BaseModel.",
    "group": "business-made"
  },
  {
    "service": "TimesheetService",
    "method": "rejectTimesheet",
    "description": "Reject a submitted timesheet — sets status rejected. Refuses unless status is \"submitted\".",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "id",
        "type": "String",
        "description": "sk of the bm_timesheet.",
        "required": true
      },
      {
        "name": "rejectedById",
        "type": "String",
        "description": "Identifier of rejecter.",
        "required": true
      },
      {
        "name": "reason",
        "type": "String",
        "description": "Free-text rejection reason.",
        "required": true
      }
    ],
    "returns": "The updated bm_timesheet BaseModel.",
    "group": "business-made"
  },
  {
    "service": "TimesheetService",
    "method": "reopenTimesheet",
    "description": "Reopen a rejected timesheet back to draft so the employee can edit and resubmit.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "id",
        "type": "String",
        "description": "sk of the bm_timesheet.",
        "required": true
      }
    ],
    "returns": "The updated bm_timesheet BaseModel.",
    "group": "business-made"
  },
  {
    "service": "TimesheetService",
    "method": "addTimeEntry",
    "description": "Append a time entry to a timesheet. Recomputes timesheet totals (regular/OT/PTO/holiday/sick). Refuses unless timesheet is draft.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "timesheetId",
        "type": "String",
        "description": "sk of the bm_timesheet.",
        "required": true
      },
      {
        "name": "entry",
        "type": "Object",
        "description": "{ date (ISO), startTime?, endTime?, breakDuration?, hours, type: regular|overtime|pto|holiday|sick|unpaid, projectId?, taskId?, description? }",
        "required": true
      }
    ],
    "returns": "The newly-added entry object.",
    "group": "business-made"
  },
  {
    "service": "TimesheetService",
    "method": "updateTimeEntry",
    "description": "Correct a time entry (date, hours, earning code, notes, break) on a draft, rejected, submitted or approved timesheet. Recomputes totals; an approved sheet goes back to submitted for re-approval; every change is kept in the entry's edit history. Refuses paid sheets and time in a pay period locked or closed for payroll.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "timesheetId",
        "type": "String",
        "description": "sk of the bm_timesheet.",
        "required": true
      },
      {
        "name": "entryId",
        "type": "String",
        "description": "id of the entry within data.timeEntries.",
        "required": true
      },
      {
        "name": "updates",
        "type": "Object",
        "description": "Partial entry patch.",
        "required": true
      },
      {
        "name": "by",
        "type": "Object",
        "required": false
      }
    ],
    "returns": "The updated bm_timesheet BaseModel.",
    "group": "business-made"
  },
  {
    "service": "TimesheetService",
    "method": "removeTimeEntry",
    "description": "Remove a time entry from a draft timesheet. Recomputes totals. Refuses unless timesheet is draft.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "timesheetId",
        "type": "String",
        "description": "sk of the bm_timesheet.",
        "required": true
      },
      {
        "name": "entryId",
        "type": "String",
        "description": "id of the entry within data.timeEntries.",
        "required": true
      }
    ],
    "returns": "The updated bm_timesheet BaseModel.",
    "group": "business-made"
  },
  {
    "service": "TimesheetService",
    "method": "clockIn",
    "description": "Clock an employee in for the current pay period. Auto-creates the period's timesheet if missing. Refuses if already clocked in.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "employeeId",
        "type": "String",
        "description": "Employee ID — the badge number, e.g. EMP-1043.",
        "required": true
      },
      {
        "name": "data",
        "type": "Object",
        "description": "Optional { projectId?, taskId?, notes? }",
        "required": true
      },
      {
        "name": "actor",
        "type": "Object",
        "required": true
      }
    ],
    "returns": "{ timesheet, entry } — the (possibly-new) timesheet and the open entry.",
    "group": "business-made"
  },
  {
    "service": "TimesheetService",
    "method": "clockOut",
    "description": "Clock an employee out — closes their open entry, computes hours from clockIn timestamp. Refuses if not clocked in.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "employeeId",
        "type": "String",
        "description": "Employee ID — the badge number, e.g. EMP-1043.",
        "required": true
      },
      {
        "name": "notes",
        "type": "String",
        "description": "Optional notes appended to the entry description.",
        "required": true
      },
      {
        "name": "capture",
        "type": "Object",
        "required": true
      }
    ],
    "returns": "{ timesheet, entry } — the timesheet and the closed entry.",
    "group": "business-made"
  },
  {
    "service": "TimesheetService",
    "method": "getActiveClockIn",
    "description": "Find the employee's currently-open clock-in entry across recent timesheets.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "employeeId",
        "type": "String",
        "description": "Employee ID — the badge number, e.g. EMP-1043.",
        "required": true
      }
    ],
    "returns": "The open entry object (with timeSheetId attached) or null.",
    "group": "business-made"
  },
  {
    "service": "TimesheetService",
    "method": "paidStateOfSheets",
    "description": "Whether each timesheet is paid, by the same rule the pay run uses: stamped by the run that paid it, or paid by a run from before stamping. Also names entries added to a paid sheet afterwards, which no run pays.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "ids",
        "type": "Array",
        "description": "sks of bm_timesheet records (one page of a list).",
        "required": true
      }
    ],
    "returns": "{ [id]: { paid, runId?, legacy?, paidAt?, unpaidEntryIds[], unpaidHours, unpaidDays[] } }",
    "group": "business-made"
  },
  {
    "service": "TimesheetService",
    "method": "getTimesheetOverlaps",
    "description": "Other timesheets of the same person whose days overlap this one, with the days both have entries on. Shown on both sheets so a manager can merge them or move entries.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "id",
        "type": "String",
        "description": "sk of the bm_timesheet.",
        "required": true
      }
    ],
    "returns": "[{ id, start, end, status, paid, entryCount, totalHours, sharedDays[], overlapStart, overlapEnd, canMoveHere, canMoveThere }]",
    "group": "business-made"
  },
  {
    "service": "TimesheetService",
    "method": "moveTimeEntries",
    "description": "Move time entries from one timesheet of a person to another of the same person (fixing overlapping sheets). Entries keep their dates and hours; nothing is deleted. Both sheets are re-totalled; an approved sheet that gains or loses entries goes back to submitted for re-approval. Paid sheets cannot change. A sheet left with no entries is marked merged (kept, never deleted).",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "fromId",
        "type": "String",
        "description": "sk of the sheet the entries leave.",
        "required": true
      },
      {
        "name": "toId",
        "type": "String",
        "description": "sk of the sheet they join (its dates must cover each entry).",
        "required": true
      },
      {
        "name": "entryIds",
        "type": "Array",
        "description": "Entry ids to move; omit to move every entry of the source that falls inside the target's dates.",
        "required": true
      },
      {
        "name": "by",
        "type": "Object",
        "description": "Who did it (audit).",
        "required": false
      }
    ],
    "returns": "{ from, to, moved, retired }",
    "group": "business-made"
  },
  {
    "service": "TimesheetService",
    "method": "mergeTimesheets",
    "description": "Merge one timesheet into another of the same person: every entry on the target's days moves across (moveTimeEntries without a pick). The source is kept; it is marked merged when nothing is left on it.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "fromId",
        "type": "String",
        "description": "sk of the sheet merged away.",
        "required": true
      },
      {
        "name": "intoId",
        "type": "String",
        "description": "sk of the sheet that keeps the entries.",
        "required": true
      },
      {
        "name": "by",
        "type": "Object",
        "description": "Who did it (audit).",
        "required": false
      }
    ],
    "returns": "{ from, to, moved, retired }",
    "group": "business-made"
  },
  {
    "service": "TimesheetService",
    "method": "getTimesheetSummary",
    "description": "Summarize an employee's hours over a date range — totals plus regular/overtime/PTO/sick splits.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "employeeId",
        "type": "String",
        "description": "Employee ID — the badge number, e.g. EMP-1043.",
        "required": true
      },
      {
        "name": "startDate",
        "type": "String",
        "description": "ISO date YYYY-MM-DD lower bound.",
        "required": true
      },
      {
        "name": "endDate",
        "type": "String",
        "description": "ISO date YYYY-MM-DD upper bound.",
        "required": true
      }
    ],
    "returns": "{ employeeId, startDate, endDate, timesheetCount, totalHours, regularHours, overtimeHours, ptoHours, sickHours }.",
    "group": "business-made"
  },
  {
    "service": "TimesheetService",
    "method": "getOnTheClock",
    "description": "Everyone currently on the clock, org-wide — the open clock-in entries with no clock-out yet.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      }
    ],
    "returns": "[{ employeeId, employeeName, orphaned, timeSheetId, entryId, clockInTime, elapsedHours, staleHours, notes }] sorted by longest shift first.",
    "group": "business-made"
  },
  {
    "service": "TimesheetService",
    "method": "closeStaleClockIns",
    "description": "Close open clock-ins that are stale (open longer than olderThanHours, default 24) or orphaned (employee deleted). Each is closed AT its clock-in time with 0 payable hours and flagged autoClosed — never given invented hours. dryRun returns the same list without writing.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "opts",
        "type": "Object",
        "required": false
      }
    ],
    "returns": "{ closed, skipped, dryRun, olderThanHours, oldestClockIn, entries: [{ timesheetId, entryId, employeeId, employeeName, reason, clockInTime, elapsedHours }] }",
    "group": "business-made"
  },
  {
    "service": "TimesheetService",
    "method": "closeOpenClockInsAt",
    "description": "Close one person's open clock-ins at a set time (their offboarding end time). The shift is paid up to that time — never past now, never before the clock-in — and flagged needsReview so an approver checks it. Offboarding calls this when the login is cut off, because the person can no longer clock out themselves.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "employeeId",
        "type": "String",
        "description": "Employee ID (badge number) on the timesheet.",
        "required": true
      },
      {
        "name": "at",
        "type": "String",
        "description": "ISO instant the shift ends.",
        "required": true
      },
      {
        "name": "reason",
        "type": "Object",
        "description": "Why it was closed, e.g. \"offboarding\".",
        "required": false
      }
    ],
    "returns": "{ closed: [{ timesheetId, entryId, clockInTime, endTime, hours }] }",
    "group": "business-made"
  },
  {
    "service": "TimesheetService",
    "method": "getTimeOverview",
    "description": "Time overview figures over every timesheet: sheets awaiting approval, overtime hours on all sheets, sheets with overtime.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      }
    ],
    "returns": "{ sheetCount, pendingApproval, overtimeHours, sheetsWithOvertime }",
    "group": "business-made"
  },
  {
    "service": "TimesheetService",
    "method": "getTeamTimesheetStatus",
    "description": "Team-wide timesheet status for a pay period — counts by status (draft/submitted/approved).",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "payPeriodStart",
        "type": "String",
        "description": "ISO date YYYY-MM-DD.",
        "required": true
      },
      {
        "name": "payPeriodEnd",
        "type": "String",
        "description": "ISO date YYYY-MM-DD.",
        "required": true
      }
    ],
    "returns": "{ payPeriodStart, payPeriodEnd, total, byStatus, pendingApproval, approved, draft }.",
    "group": "business-made"
  },
  {
    "service": "TimesheetService",
    "method": "getMissingTimesheets",
    "description": "Active hourly/mixed employees with NO timesheet for the period — surfaces the gap pre-payroll.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "required": true
      },
      {
        "name": "payPeriodStart",
        "type": "String",
        "description": "ISO date YYYY-MM-DD.",
        "required": true
      },
      {
        "name": "payPeriodEnd",
        "type": "String",
        "description": "ISO date YYYY-MM-DD.",
        "required": true
      }
    ],
    "returns": "{ payPeriodStart, payPeriodEnd, missing: [{ employeeId, name, payType, email }] }",
    "group": "business-made"
  }
]
